insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Deixar de parar o veículo antes de transpor linha férrea é infração gravíssima, com multa.', '["Infração gravíssima."]'::jsonb, '["Gravíssima; parar antes da linha férrea."]'::jsonb, 'Atravessar a ferrovia sem parar é infração gravíssima.', '["Assertiva que classifica como grave a falta de parada antes da linha férrea erra: é gravíssima."]'::jsonb, '[]'::jsonb, '["Art. 32"]'::jsonb, 'under_review', 'claude'
