insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Deixar de parar o veículo sempre que a respectiva marcha for interceptada por agrupamento de pessoas, como préstitos, passeatas e desfiles, é infração gravíssima, com multa; se interceptada por agrupamento de veículos, como cortejos e formações militares, é infração grave, com multa.', '["Agrupamento de pessoas: gravíssima.","Agrupamento de veículos: grave."]'::jsonb, '["Pessoas = GRAVÍSSIMA; veículos = GRAVE."]'::jsonb, 'Furar a passeata é infração gravíssima.', '["Assertiva que classifica como gravíssima a interceptação por cortejo de veículos erra: é grave."]'::jsonb, '[]'::jsonb, '["Art. 205"]'::jsonb, 'under_review', 'claude'
