insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Deixar de dar preferência de passagem em interseção não sinalizada a veículo que estiver circulando por rodovia ou rotatória e a veículo que vier da direita, bem como nas interseções com sinalização de regulamentação de Dê a Preferência, é infração grave, com multa.', '["Infração grave.","Interseção não sinalizada: rodovia, rotatória e veículo da direita.","Sinal de Dê a Preferência."]'::jsonb, '["Sem sinalização, preferência de quem vem da direita."]'::jsonb, 'Em cruzamento sem placa, cede-se a vez a quem vem da direita.', '["Assertiva que dá preferência ao veículo da esquerda em interseção não sinalizada erra."]'::jsonb, '[]'::jsonb, '["Art. 29"]'::jsonb, 'under_review', 'claude'
