insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Entrar ou sair de áreas lindeiras sem estar adequadamente posicionado para ingresso na via e sem as precauções com a segurança de pedestres e de outros veículos é infração média, com multa.', '["Infração média."]'::jsonb, '["Média."]'::jsonb, 'Sair da garagem sem se posicionar e sem cuidado é infração média.', '["Assertiva que classifica como gravíssima a saída irregular de áreas lindeiras erra: é média."]'::jsonb, '[]'::jsonb, '["Art. 36"]'::jsonb, 'under_review', 'claude'
