insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Transitar em velocidade superior à máxima permitida para o local, medida por instrumento ou equipamento hábil, é infração média quando a velocidade for superior à máxima em até 20%, grave quando for superior em mais de 20% até 50%, e gravíssima, com multa (três vezes) e suspensão do direito de dirigir, quando for superior em mais de 50%.', '["Até 20% acima: média.","De mais de 20% até 50% acima: grave.","Mais de 50% acima: gravíssima, multa três vezes e suspensão."]'::jsonb, '["Faixas: 20% e 50% acima da velocidade máxima.","Acima de 50%: suspensão do direito de dirigir."]'::jsonb, 'Em via de sessenta, andar a cento e dez é mais de 50% acima: infração gravíssima.', '["Assertiva que classifica como média o excesso superior a 50% erra: é gravíssima."]'::jsonb, '[]'::jsonb, '["Art. 61"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-218'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

