select u.id, u.content_sha256, 'Transitar com o veículo em velocidade inferior à metade da velocidade máxima estabelecida para a via, retardando ou obstruindo o trânsito, a menos que as condições de tráfego e meteorológicas não o permitam, salvo se estiver na faixa da direita, é infração média, com multa.', '["Infração média.","Velocidade inferior à metade da máxima.","Exceção: faixa da direita."]'::jsonb, '["Média; exceção para a faixa da direita."]'::jsonb, 'Dirigir a vinte em via de oitenta, obstruindo o fluxo na faixa da esquerda, gera multa.', '["Assertiva que isenta a velocidade baixa na faixa da esquerda erra: a exceção é para a faixa da direita."]'::jsonb, '[]'::jsonb, '["Art. 62"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-219'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Deixar de reduzir a velocidade do veículo de forma compatível com a segurança do trânsito é infração gravíssima quando ao aproximar-se de passeatas, aglomerações, cortejos, préstitos e desfiles, ao ultrapassar ciclista e nas proximidades de escolas, hospitais, estações de embarque e desembarque ou onde haja intensa movimentação de pedestres. É infração grave nas demais hipóteses, como onde o trânsito é controlado pelo agente, ao aproximar-se do meio-fio, de interseção não sinalizada, em curvas fechadas, em obras, sob chuva ou neblina, com má visibilidade, pavimento escorregadio, animais na pista ou em declive.', '["Gravíssima: aglomerações, ultrapassagem de ciclista e proximidades de escolas e hospitais.","Grave: chuva, neblina, curva, obras, declive e outras hipóteses."]'::jsonb, '["Ao ultrapassar ciclista: GRAVÍSSIMA.","ATUALIZAÇÃO: ultrapassagem de ciclista foi incluída por lei posterior."]'::jsonb, 'Passar em alta velocidade perto de uma escola é infração gravíssima.', '["Assertiva que classifica como média a falta de redução da velocidade ao ultrapassar ciclista erra: é gravíssima."]'::jsonb, '[]'::jsonb, '["Art. 43"]'::jsonb, 'under_review', 'claude'
