insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Portar no veículo placas de identificação em desacordo com as especificações e modelos do Contran é infração média, com multa e a medida administrativa de retenção do veículo para regularização e apreensão das placas irregulares. Incide na mesma penalidade quem confecciona, distribui ou coloca placas não autorizadas.', '["Infração média.","Retenção do veículo e apreensão das placas.","Atinge quem confecciona, distribui ou coloca placas irregulares."]'::jsonb, '["Alcança também quem fabrica ou coloca a placa irregular."]'::jsonb, 'A loja que confecciona placa fora do padrão responde pela infração.', '["Assertiva que limita a infração ao condutor do veículo erra."]'::jsonb, '[]'::jsonb, '["Art. 115"]'::jsonb, 'under_review', 'claude'
