select u.id, u.content_sha256, 'Transitar com o farol desregulado ou com o facho de luz alta de forma a perturbar a visão de outro condutor é infração grave, com multa e a medida administrativa de retenção do veículo para regularização.', '["Infração grave.","Retenção para regularização."]'::jsonb, '["Grave, com retenção."]'::jsonb, 'Dirigir com farol alto ofuscando quem vem em sentido contrário gera multa grave.', '["Assertiva que classifica como leve o farol desregulado erra: é grave."]'::jsonb, '[]'::jsonb, '["Art. 40"]'::jsonb, 'under_review', 'claude'
