insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Deixar de sinalizar a via, de forma a prevenir os demais condutores e, à noite, não manter acesas as luzes externas ou omitir-se quanto a providências necessárias para tornar visível o local, quando tiver de remover o veículo da pista de rolamento ou permanecer no acostamento, ou quando a carga for derramada sobre a via e não puder ser retirada imediatamente, é infração grave, com multa.', '["Infração grave.","Veículo parado no acostamento ou carga derramada."]'::jsonb, '["Grave."]'::jsonb, 'Deixar de colocar o triângulo ao parar no acostamento à noite gera multa.', '["Assertiva que dispensa a sinalização com carga derramada na via erra."]'::jsonb, '[]'::jsonb, '["Art. 46"]'::jsonb, 'under_review', 'claude'
