insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Deixar de sinalizar qualquer obstáculo à livre circulação, à segurança de veículo e pedestres, tanto no leito da via como na calçada, ou obstaculizar a via indevidamente é infração gravíssima, com multa agravada em até cinco vezes, a critério da autoridade, conforme o risco à segurança. A penalidade é aplicada à pessoa física ou jurídica responsável pela obstrução, e a autoridade providencia a sinalização de emergência às expensas do responsável.', '["Infração gravíssima.","Multa agravada em até cinco vezes.","Responsável pela obstrução."]'::jsonb, '["Multa agravada em até CINCO vezes."]'::jsonb, 'A obra na calçada sem sinalização gera multa agravada à empresa.', '["Assertiva que fixa multa simples sem possibilidade de agravamento erra: pode ser agravada em até cinco vezes."]'::jsonb, '[]'::jsonb, '["Art. 94"]'::jsonb, 'under_review', 'claude'
