insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Deixar de conduzir pelo bordo da pista de rolamento, em fila única, os veículos de tração ou propulsão humana e os de tração animal, sempre que não houver acostamento ou faixa a eles destinados, é infração média, com multa.', '["Infração média.","Fila única pelo bordo da pista."]'::jsonb, '["Média."]'::jsonb, 'A carroça deve seguir pelo bordo da pista, em fila única.', '["Assertiva que permite a circulação de carroças ao centro da pista erra."]'::jsonb, '[]'::jsonb, '["Art. 52"]'::jsonb, 'under_review', 'claude'
