insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Qualquer concentração de álcool por litro de sangue ou por litro de ar alveolar sujeita o condutor às penalidades do art. 165. O Contran disciplina as margens de tolerância quando a infração for apurada por meio de aparelho de medição, observada a legislação metrológica.', '["Qualquer concentração de álcool.","Margens de tolerância pelo Contran para aparelhos."]'::jsonb, '["Tolerância zero: não há limite mínimo de concentração.","Margem de tolerância do aparelho é definida pelo Contran."]'::jsonb, 'Mesmo uma pequena concentração de álcool configura a infração do art. 165.', '["Assertiva que admite uma concentração mínima de álcool sem infração erra."]'::jsonb, '[{"termo":"Tolerância zero","significado":"Qualquer concentração de álcool configura infração administrativa."}]'::jsonb, '["Art. 165"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-276'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O condutor de veículo automotor envolvido em sinistro de trânsito ou que for alvo de fiscalização pode ser submetido a teste, exame clínico, perícia ou outro procedimento que, por meios técnicos ou científicos, na forma do Contran, permita certificar influência de álcool ou outra substância psicoativa que determine dependência. A infração do art. 165 também pode ser caracterizada mediante imagem, vídeo, constatação de sinais de alteração da capacidade psicomotora ou outras provas admitidas em direito.', '["Testes, exames e perícias.","Infração do art. 165 comprovável por imagem, vídeo e sinais."]'::jsonb, '["A infração pode ser provada mesmo sem o bafômetro.","Recusar ao teste é infração própria (art. 165-A)."]'::jsonb, 'O vídeo mostrando sinais de embriaguez pode comprovar a infração.', '["Assertiva que só admite o bafômetro como prova da embriaguez erra."]'::jsonb, '[]'::jsonb, '["Art. 165-A"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-277'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O condutor que se evadir da fiscalização, não submetendo o veículo à pesagem obrigatória nos pontos de pesagem fixos ou móveis, sofre a penalidade do art. 209, além da obrigação de retornar ao ponto de evasão para a pesagem. Em caso de fuga à ação policial, a apreensão do veículo se dá tão logo seja localizado, aplicando-se também as penalidades do art. 210.', '["Evasão da pesagem: art. 209 e retorno ao ponto de pesagem.","Fuga à ação policial: apreensão e art. 210."]'::jsonb, '["Dois efeitos: penalidade e obrigação de voltar à pesagem."]'::jsonb, 'O caminhoneiro que desvia da balança retorna ao posto para ser pesado.', '["Assertiva que dispensa o retorno do condutor ao ponto de pesagem erra."]'::jsonb, '[]'::jsonb, '["Art. 209"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-278'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O condutor que usar veículo para a prática dos crimes de receptação, descaminho ou contrabando, condenado em decisão transitada em julgado, tem cassado seu documento de habilitação ou é proibido de obter a habilitação pelo prazo de cinco anos. O condenado pode requerer reabilitação, submetendo-se a todos os exames. No caso de preso em flagrante, o juiz pode decretar, como medida cautelar, a suspensão da habilitação ou a proibição de sua obtenção.', '["Cassação ou proibição por cinco anos.","Reabilitação mediante exames.","Cautelar na prisão em flagrante."]'::jsonb, '["Prazo de cinco anos.","ATUALIZAÇÃO: artigo incluído por lei posterior."]'::jsonb, 'O motorista condenado por contrabando com o veículo perde a habilitação por cinco anos.', '["Assertiva que fixa em um ano o prazo da proibição erra: são cinco anos."]'::jsonb, '[]'::jsonb, '["Art. 294"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-278-a'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Em caso de sinistro com vítima envolvendo veículo equipado com registrador instantâneo de velocidade e tempo, somente o perito oficial encarregado do levantamento pericial pode retirar o disco ou a unidade armazenadora do registro.', '["Só o perito oficial retira o disco ou a unidade do registrador."]'::jsonb, '["Preserva a prova do tacógrafo."]'::jsonb, 'Após o sinistro com vítima, só o perito retira o disco do tacógrafo.', '["Assertiva que permite ao condutor retirar o disco do tacógrafo após o sinistro erra."]'::jsonb, '[]'::jsonb, '["Art. 105"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-279'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O veículo em estado de abandono ou sinistrado pode ser removido para o depósito fixado pelo órgão competente, independentemente da existência de infração, nos termos da regulamentação do Contran. A remoção do veículo sinistrado é realizada quando não houver responsável por ele no local. Aplicam-se as disposições do art. 328, sem prejuízo das demais disposições do Código.', '["Remoção de veículo abandonado ou sinistrado.","Independe de infração.","Veículo sinistrado: quando não houver responsável no local."]'::jsonb, '["ATUALIZAÇÃO: artigo incluído por lei posterior."]'::jsonb, 'O carro abandonado na via é removido ao depósito sem que haja infração.', '["Assertiva que exige infração para remover veículo abandonado erra."]'::jsonb, '[]'::jsonb, '["Art. 328"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-279-a'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Ocorrendo infração, lavra-se auto de infração com a tipificação da infração; local, data e hora; caracteres da placa, marca e espécie do veículo; o prontuário do condutor, sempre que possível; a identificação do órgão e da autoridade, agente ou equipamento que comprovou a infração; e a assinatura do infrator, sempre que possível, valendo esta como notificação. A infração é comprovada por declaração da autoridade ou do agente, por aparelho eletrônico, equipamento audiovisual ou outro meio tecnológico regulamentado pelo Contran. O agente pode ser servidor civil ou policial militar designado pela autoridade de trânsito.', '["Elementos do auto de infração.","Comprovação por declaração, equipamento eletrônico ou meio tecnológico.","Agente civil ou policial militar designado."]'::jsonb, '["A assinatura do infrator vale como notificação, quando possível."]'::jsonb, 'O radar registra a infração e identifica o equipamento no auto.', '["Assertiva que exige sempre a assinatura do infrator no auto de infração erra: é sempre que possível."]'::jsonb, '[{"termo":"Auto de infração","significado":"Documento que registra a infração de trânsito constatada."}]'::jsonb, '["Art. 281"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-280'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A autoridade de trânsito julga a consistência do auto de infração e aplica a penalidade cabível. O auto é arquivado e seu registro julgado insubsistente se for considerado inconsistente ou irregular ou se, no prazo máximo de trinta dias, não for expedida a notificação da autuação. O prazo para a notificação das penalidades de suspensão do direito de dirigir e de cassação conta-se da instauração do processo destinado à aplicação dessas penalidades.', '["Julgamento da consistência do auto.","Arquivamento se inconsistente.","Notificação da autuação em até trinta dias."]'::jsonb, '["Trinta dias para a notificação da autuação, sob pena de arquivamento."]'::jsonb, 'Sem notificação em trinta dias, o auto de infração é arquivado.', '["Assertiva que fixa em sessenta dias o prazo para a notificação da autuação erra: são trinta dias."]'::jsonb, '[]'::jsonb, '["Art. 282"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-281'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Na notificação de autuação e no auto de infração, quando valer como notificação, deve constar o prazo para apresentação de defesa prévia, que não será inferior a trinta dias, contado da data de expedição da notificação.', '["Prazo de defesa prévia de, no mínimo, trinta dias."]'::jsonb, '["ATUALIZAÇÃO: artigo incluído por lei posterior.","Mínimo de trinta dias."]'::jsonb, 'A notificação informa que o condutor tem ao menos trinta dias para a defesa prévia.', '["Assertiva que admite prazo de defesa prévia inferior a trinta dias erra."]'::jsonb, '[]'::jsonb, '["Art. 282"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-281-a'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Caso a defesa prévia seja indeferida ou não seja apresentada no prazo, é aplicada a penalidade e expedida notificação ao proprietário do veículo ou ao infrator, por remessa postal ou meio tecnológico que assegure a ciência. A notificação devolvida por desatualização de endereço ou recusa é válida para todos os efeitos. Quando a multa é imposta ao condutor, a notificação é encaminhada ao proprietário, responsável pelo pagamento. Da notificação constará a data do término do prazo para recurso, não inferior a trinta dias, que será também a data de recolhimento da multa. As notificações das penalidades do art. 256 têm prazo de expedição de cento e oitenta dias.', '["Notificação da penalidade após o indeferimento ou a falta de defesa.","Notificação devolvida por endereço desatualizado é válida.","Prazo de recurso de, no mínimo, trinta dias.","Expedição das notificações em cento e oitenta dias."]'::jsonb, '["Notificação devolvida por endereço desatualizado: VÁLIDA.","ATUALIZAÇÃO: o rito de defesa prévia foi incluído por lei posterior."]'::jsonb, 'A notificação devolvida por mudança de endereço não invalida a penalidade.', '["Assertiva que invalida a notificação devolvida por endereço desatualizado erra."]'::jsonb, '[]'::jsonb, '["Art. 281-A"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-282'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O órgão responsável pela autuação deve oferecer ao proprietário ou condutor autuado a opção de notificação por meio eletrônico, na forma do Contran. O proprietário e o condutor mantêm o cadastro atualizado no órgão executivo de trânsito do Estado ou do Distrito Federal. Nessa hipótese, o proprietário ou condutor é considerado notificado trinta dias após a inclusão da informação no sistema eletrônico e o envio da mensagem.', '["Opção de notificação eletrônica.","Cadastro atualizado.","Considerado notificado trinta dias após a inclusão no sistema."]'::jsonb, '["ATUALIZAÇÃO: artigo incluído por lei posterior.","Notificado após TRINTA dias."]'::jsonb, 'O condutor aderente ao sistema eletrônico é considerado notificado trinta dias após o envio.', '["Assertiva que considera notificado o condutor no mesmo dia da mensagem erra: são trinta dias."]'::jsonb, '[]'::jsonb, '["Art. 284"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-282-a'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

